    for i = 1, 190 do
        local dot = Instance.new("Frame")
        local diameter = rng:NextInteger(2, 5)
        dot.Name = "Snowflake"
        dot.AnchorPoint = Vector2.new(0.5, 0.5)
        dot.Size = UDim2.fromOffset(diameter, diameter)
        dot.Position = UDim2.fromScale(rng:NextNumber(), rng:NextNumber())
        dot.BackgroundColor3 = Color3.fromRGB(245, 248, 255)
        dot.BackgroundTransparency = rng:NextNumber(0.05, 0.38)
        dot.BorderSizePixel = 0
        dot.ZIndex = 2
        dot.Parent = snowLayer
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = dot
        flakes[i] = {
            ui = dot,
            x = rng:NextNumber(),
            y = rng:NextNumber(),
            fall = rng:NextNumber(0.055, 0.19),
            drift = rng:NextNumber(-0.018, 0.018),
            sway = rng:NextNumber(0.004, 0.018),
            phase = rng:NextNumber(0, math.pi * 2),
        }
    end

    local skip = Instance.new("TextButton")
    skip.Name = "SkipIntro"
    skip.Size = UDim2.fromScale(1, 1)
    skip.BackgroundTransparency = 1
    skip.Text = ""
    skip.AutoButtonColor = false
    skip.ZIndex = 10
    skip.Parent = background
