    introSound = Instance.new("Sound")
    introSound.Name = "MonsterIntroMusic"
    introSound.SoundId = MONSTER_INTRO_SOUND_ID
    introSound.Volume = 1
    introSound.Looped = false
    introSound.Parent = SoundService
    task.spawn(function()
        pcall(function()
            game:GetService("ContentProvider"):PreloadAsync({introSound})
            if not finished and introSound and introSound.Parent then introSound:Play() end
        end)
    end)

    table.insert(connections, RunService.RenderStepped:Connect(function(dt)
        if finished or not screenGui.Parent then return end
        local t = os.clock()
        for _, flake in ipairs(flakes) do
            flake.y = flake.y + flake.fall * dt
            flake.x = flake.x + flake.drift * dt + math.sin(t * 1.1 + flake.phase) * flake.sway * dt
            if flake.y > 1.04 then
