40,0},glare=3,haze=3.2},clouds={cover=0.7,dens=0.7,color={200,80,40}}}, ["Mint Sky"]={clock=10,brightness=3.2,ambient={180,230,210},outAmb={190,240,220},sky={sun=10},atm={dens=0.32,color={150,255,210},decay={100,220,180},glare=1.6,haze=1.6},clouds={cover=0.55,dens=0.45,color={240,255,250}}}, } local function _vC3(t) return Color3.fromRGB(t[1], t[2], t[3]) end function _v4mpClearSky() for _, child in ipairs(Lighting:GetChildren()) do if child:GetAttribute("_AdaptDuelsSky") then pcall(function() child:Destroy() end) end end local terrain = workspace:FindFirstChildOfClass("Terrain") if terrain then for _, child in ipairs(terrain:GetChildren()) do if child:GetAttribute("_AdaptDuelsSky") then pcall(function() child:Destroy() end) end end end end function applyCustomSky(mode) _v4mpClearSky() local preset = SKY_PRESETS[mode] if not preset or preset.kind == "off" then Lighting.ClockTime = 14 Lighting.Brightness = 2 Lighting.OutdoorAmbient = Color3.fromRGB(127,127,127) Lighting.Ambient = Color3.fromRGB(127,127,127) Lighting.FogEnd = 100000 Lighting.GlobalShadows = true skyTheme = "Off" return end Lighting.FogStart = 0 Lighting.FogEnd = 100000 Lighting.FogColor = Color3.fromRGB(188, 230, 205) Lighting.ColorShift_Top = Color3.fromRGB(0,0,0) Lighting.ColorShift_Bottom = Color3.fromRGB(0,0,0) Lighting.GlobalShadows = true Lighting.ClockTime = preset.clock or 14 Lighting.Brightness = preset.brightness or 2 if preset.outAmb then Lighting.OutdoorAmbient = _vC3(preset.outAmb) end if preset.ambient then Lighting.Ambient = _vC3(preset.ambient) end if preset.sky then local skyInst = Instance.new("Sky") skyInst:SetAttribute("_AdaptDuelsSky", true) if preset.sky.stars then skyInst.StarCount = preset.sky.stars end if preset.sky.moon then skyInst.MoonAngularSize = preset.sky.moon end if preset.sky.sun then skyInst.SunAngularSize = preset.sky.sun end if preset.sky.moonTex then skyInst.MoonTextureId = "rbxasset://sky/moon.jpg" end skyInst.Parent = Lighting end if preset.atm then local atm = Instance.new("Atmosphere") atm:SetAttribute("_AdaptDuelsSky", true) atm.Density = preset.atm.dens or 0.3 atm.Color = _vC3(preset.atm.color) atm.Decay = _vC3(preset.atm.decay) atm.Glare = preset.atm.glare or 1 atm.Haze = preset.atm.haze or 1 atm.Parent = Lighting end local terrain = workspace:FindFirstChildOfClass("Terrain") if preset.clouds and terrain then local clouds = Instance.new("Clouds") clouds:SetAttribute("_AdaptDuelsSky", true) clouds.Cover = preset.clouds.cover or 0.5 clouds.Density = preset.clouds.dens or 0.5 clouds.Color = _vC3(preset.clouds.color) clouds.Parent = terrain end skyTheme = mode end local function applyNeonWeather() if not neonWeatherEnabled then restoreLightingState() return end if not _originalLighting then saveLightingState() end Lighting.Brightness = 3.5 Lighting.ClockTime = 20 Lighting.OutdoorAmbient = Color3.fromRGB(80, 20, 20) Lighting.GlobalShadows = false Lighting.FogEnd = 300 Lighting.FogStart = 0 Lighting.FogColor = Color3.fromRGB(200, 0, 0) Lighting.Ambient = Color3.fromRGB(120, 30, 30) local cc = Lighting:FindFirstChildOfClass("ColorCorrectionEffect") if not cc then cc = Instance.new("ColorCorrectionEffect") cc.Parent = Lighting end cc.Enabled = true cc.Brightness = 0.2 cc.Contrast = 0.15 cc.Saturation = 0.15 cc.TintColor = Color3.fromRGB(255, 200, 200) local bloom = Lighting:FindFirstChildOfClass("BloomEffect") if not bloom then bloom = Instance.new("BloomEffect") bloom.Parent = Lighting end bloom.Enabled = true bloom.Intensity = 0.6 bloom.Size = 25 bloom.Threshold = 0.8 end function toggleNeonWeather(state) if state == nil then neonWeatherEnabled = not neonWeatherEnabled else neonWeatherEnabled = state end applyNeonWeather() if setNeonWeatherVisual then setNeonWeatherVisual(neonWeatherEnabled) end end local function attachFloatingSnow(target, baseZ)
 if not target or target:FindFirstChild("FloatingSnowOverlay") then return end
 target.ClipsDescendants = true
 local overlay = Instance.new("Frame")
 overlay.Name = "FloatingSnowOverlay"
 overlay.Size = UDim2.new(1, 0, 1, 0)
 overlay.BackgroundTransparency = 1
 overlay.BorderSizePixel = 0
 overlay.Active = false
 overlay.Selectable = false
 overlay.ZIndex = (baseZ or target.ZIndex or 1) + 2
 overlay.Parent = target
 local corner = Instance.new("UICorner", overlay)
 corner.CornerRadius = UDim.new(0, 9)
 -- Small icy drips along the lower edge, like the reference video.
 for i = 1, 5 do
  local drip = Instance.new("Frame")
  drip.Name = "IceDrip"
  drip.AnchorPoint = Vector2.new(0.5, 0)
  drip.Position = UDim2.new((i - 0.5) / 5, 0, 1, -12)
  drip.Size = UDim2.new(0, (i % 2 == 0) and 3 or 2, 0, 7 + ((i * 5) % 9))
  drip.BackgroundColor3 = (i % 2 == 0) and Color3.fromRGB(205, 235, 255) or Color3.fromRGB(245, 250, 255)
  drip.BackgroundTransparency = 0.18
  drip.BorderSizePixel = 0
  drip.ZIndex = overlay.ZIndex + 1
  drip.Parent = overlay
  Instance.new("UICorner", drip).CornerRadius = UDim.new(1, 0)
 end
 -- Animated snowflakes fall continuously inside each button.
 for i = 1, 9 do
  local flake = Instance.new("Frame")
  flake.Name = "Snowflake"
  flake.Size = UDim2.fromOffset((i % 2 == 0) and 3 or 2, (i % 2 == 0) and 3 or 2)
  flake.Position = UDim2.new(((i * 19) % 90) / 100, 0, -0.15 - (i * 0.13), 0)
  flake.BackgroundColor3 = Color3.fromRGB(240, 248, 255)
  flake.BackgroundTransparency = 0.12
  flake.BorderSizePixel = 0
  flake.ZIndex = overlay.ZIndex + 2
  flake.Parent = overlay
  Instance.new("UICorner", flake).CornerRadius = UDim.new(1, 0)
  task.spawn(function()
   local offset = i * 0.17
   while flake.Parent and overlay.Parent do
    local duration = 1.25 + (i % 4) * 0.38
    local tween = TS:Create(flake, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
     Position = UDim2.new(((i * 19) % 90) / 100, 0, 1.12, 0),
     BackgroundTransparency = 0.35
    })
    tween:Play()
    tween.Completed:Wait()
    if not flake.Parent then break end
    flake.Position = UDim2.new(((i * 19 + 23) % 90) / 100, 0, -0.12, 0)
    flake.BackgroundTransparency = 0.12
    task.wait(offset)
   end
  end)
 end
end
