Text.TextYAlignment = Enum.TextYAlignment.Center infoText.ZIndex = 8 end _G.__MonsterStylesReset = function() setFeature("Corpo R15", false) setFeature("Violette Custom Skins", false) setFeature("Animations", false) setFeature("Headless Visual", false) setFeature("Korblox Visual", false) violetteSkinMode = _G.__MonsterDefaultSkinKey or "1" _G._KawatanSkinColor = violetteSkinMode for key in pairs(customAnimationIds) do customAnimationIds[key] = nil end if customPanel then for _, child in ipairs(customPanel:GetDescendants()) do if child:IsA("TextBox") then child.Text = "" end end customPanel.Visible = false end selectedChoiceIndex = 1 selectedSourcePreset = animationChoiceNames[1] _G.__CrystalAnimationPreset = selectedSourcePreset if presetLabel then presetLabel.Text = selectedSourcePreset end if skinSelectorLabel then skinSelectorLabel.Text = skinLabel("1") end saveConfig() end end) if not okSets then warn("[Sets] " .. tostring(errSets)) end end do local okFx, errFx = pcall(function() local page = contentPages["Styles"] if not page then return end local Players = game:GetService("Players") local RunService = game:GetService("RunService") local TweenService = game:GetService("TweenService") local HttpService = game:GetService("HttpService") local LPl = Players.LocalPlayer if _G.__MonsterCosmetics and _G.__MonsterCosmetics.Destroy then pcall(_G.__MonsterCosmetics.Destroy) end local FILE = "MonsterHub_Cosmetics.json" local saved = {} pcall(function() if type(isfile) == "function" and type(readfile) == "function" and isfile(FILE) then local d = HttpService:JSONDecode(readfile(FILE)) if type(d) == "table" then saved = d end end end) local EFFECTS = {"Electric Aura", "Orbital Rings", "Neon Wings", "Ghost Trail", "Glowing Steps", "Ice Aura", "Cosmic Aura"} local state = {} for _, n in ipairs(EFFECTS) do state[n] = type(saved.effects) == "table" and saved.effects[n] == true end local SWATCHES = { Color3.fromRGB(240, 120, 55), Color3.fromRGB(235, 70, 80), Color3.fromRGB(250, 225, 120), Color3.fromRGB(120, 250, 130), Color3.fromRGB(100, 215, 255), Color3.fromRGB(70, 110, 245), Color3.fromRGB(170, 80, 245), Color3.fromRGB(255, 95, 190), } local effectColor = SWATCHES[4] local function toHex(c) return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end local function parseColor(txt) txt = tostring(txt or ""):gsub("%s", "") local hex = txt:match("^#?(%x%x%x%x%x%x)$") if hex then return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16)) end local r, g, b = txt:match("^(%d+),(%d+),(%d+)$") if r then return Color3.fromRGB(math.clamp(tonumber(r), 0, 255), math.clamp(tonumber(g), 0, 255), math.clamp(tonumber(b), 0, 255)) end return nil end if type(saved.color) == "string" then local c = parseColor(saved.color) if c then effectColor = c end end local fxFolder = Instance.new("Folder") fxFolder.Name = "MonsterCosmeticFX" fxFolder.Parent = workspace local function save() if type(writefile) ~= "function" then return end pcall(function() writefile(FILE, HttpService:JSONEncode({effects = state, color = toHex(effectColor)})) end) end local function newPart(size, shape) local p = Instance.new("Part") p.Size = size if shape then p.Shape = shape end p.Material = Enum.Material.Neon p.Anchored = true p.CanCollide = false p.CanQuery = false p.CanTouch = false p.CastShadow = false p.Massless = true p.Color = effectColor p.Parent = fxFolder return p end local NSK, CSK = NumberSequenceKeypoint.new, ColorSequenceKeypoint.new local SPARK = "rbxasset://textures/particles/sparkles_main.dds" local STARTERS = {} STARTERS["Electric Aura"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local em = Instance.new("ParticleEmitter") em.Texture = SPARK em.LightEmission = 1 em.Rate = 45 em.Lifetime = NumberRange.new(0.25, 0.55) em.Speed = NumberRange.new(6, 14) em.SpreadAngle = Vector2.new(180, 180) em.RotSpeed = NumberRange.new(-300, 300) em.Size = NumberSequence.new({NSK(0, 0.55), NSK(1, 0)}) em.Transparency = NumberSequence.new({NSK(0, 0), NSK(1, 1)}) em.Parent = root local light = Instance.new("PointLight") light.Range = 10 light.Parent = root local function recolor(c) em.Color = ColorSequence.new(c, Color3.new(1, 1, 1)) light.Color = c end recolor(effectColor) local conn = RunService.Heartbeat:Connect(function() light.Brightness = 1.2 + math.random() * 2.5 end) return {recolor = recolor, cleanup = function() conn:Disconnect(); em:Destroy(); light:Destroy() end} end STARTERS["Orbital Rings"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local R = 3.3 local disc = newPart(Vector3.new(0.1, R * 2, R * 2), Enum.PartType.Cylinder) disc.Transparency = 0.55 local rim = newPart(Vector3.new(0.14, R * 2 + 0.2, R * 2 + 0.2), Enum.PartType.Cylinder) rim.Transparency = 0.82 local SP = 16 local spikes = {} for i = 1, SP do local p = newPart(Vector3.new(0.16, 0.16, 1.3)) p.Transparency = 0.15 spikes[i] = p end local t = 0 local conn = RunService.RenderStepped:Connect(function(dt) t = t + dt if not root.Parent then return end local center = root.Position + Vector3.new(0, 1.6, 0) local tilt = CFrame.Angles(math.sin(t * 1.3) * math.rad(4), 0, math.sin(t * 0.9) * math.rad(4)) local flat = CFrame.new(center) * tilt disc.CFrame = flat * CFrame.Angles(0, 0, math.rad(90)) rim.CFrame = disc.CFrame for i, p in ipairs(spikes) do local ang = t * 0.9 + (i / SP) * math.pi * 2 local dir = Vector3.new(math.cos(ang), 0, math.sin(ang)) local pos = (flat * CFrame.new(dir * R)).Position local target = (flat * CFrame.new(dir * (R + 0.6) + Vector3.new(0, 1.1, 0))).Position p.CFrame = CFrame.lookAt(pos, target) * CFrame.new(0, 0, -0.65) end end) local function recolor(c) disc.Color = c rim.Color = c for _, p in ipairs(spikes) do p.Color = c end end return {recolor = recolor, cleanup = function() conn:Disconnect() disc:Destroy(); rim:Destroy() for _, p in ipairs(spikes) do p:Destroy() end end} end STARTERS["Neon Wings"] = function(char) local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") if not torso then return end local COUNT = 6 local feathers = {} for side = -1, 1, 2 do for i = 1, COUNT do local len = 3.4 - (i - 1) * 0.38 local p = newPart(Vector3.new(0.5, 0.06, len)) p.Transparency = 0.1 + (i - 1) * 0.05 feathers[#feathers + 1] = {part = p, side = side, i = i, len = len} end end local t = 0 local conn = RunService.RenderStepped:Connect(function(dt) t = t + dt if not torso.Parent then return end local flap = math.sin(t * 2.2) * math.rad(10) local base = torso.CFrame for _, f in ipairs(feathers) do local yaw = math.rad(35 + (f.i - 1) * 9) + flap local pitch = -(math.rad(50) - math.rad((f.i - 1) * 12)) + flap * 0.5 f.part.CFrame = base * CFrame.new(f.side * 0.45, 0.5, 0.5) * CFrame.Angles(0, f.side * yaw, 0) * CFrame.Angles(pitch, 0, 0) * CFrame.new(0, 0, f.len / 2) end end) local function recolor(c) for _, f in ipairs(feathers) do f.part.Color = c end end return {recolor = recolor, cleanup = function() conn:Disconnect() for _, f in ipairs(feathers) do f.part:Destroy() end end} end STARTERS["Ghost Trail"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local a0 = Instance.new("Attachment", root) a0.Position = Vector3.new(0, 1.6, 0) local a1 = Instance.new("Attachment", root) a1.Position = Vector3.new(0, -1.8, 0) local tr = Instance.new("Trail") tr.Attachment0 = a0 tr.Attachment1 = a1 tr.Lifetime = 0.9 tr.LightEmission = 1 tr.FaceCamera = true tr.MinLength = 0.05 tr.Transparency = NumberSequence.new({NSK(0, 0.35), NSK(1, 1)}) tr.WidthScale = NumberSequence.new({NSK(0, 1), NSK(1, 0.3)}) tr.Parent = root local function recolor(c) tr.Color = ColorSequence.new(c, Color3.fromRGB(230, 230, 255)) end recolor(effectColor) return {recolor = recolor, cleanup = function() tr:Destroy(); a0:Destroy(); a1:Destroy() end} end STARTERS["Glowing Steps"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") local hum = char:FindFirstChildOfClass("Humanoid") if not root or not hum then return end local acc, flip = 0, 1 local conn = RunService.Heartbeat:Connect(function(dt) acc = acc + dt if acc < 0.2 then return end if hum.MoveDirection.Magnitude < 0.1 or hum.FloorMaterial == Enum.Material.Air then return end acc = 0 flip = -flip local pos = root.Position + root.CFrame.RightVector * flip * 0.9 + Vector3.new(0, -(hum.HipHeight + root.Size.Y / 2) + 0.08, 0) local d = newPart(Vector3.new(0.06, 1.8, 1.8), Enum.PartType.Cylinder) d.Transparency = 0.25 d.CFrame = CFrame.new(pos) * CFrame.Angles(0, 0, math.rad(90)) TweenService:Create(d, TweenInfo.new(1.1), {Transparency = 1, Size = Vector3.new(0.06, 3, 3)}):Play() task.delay(1.3, function() pcall(function() d:Destroy() end) end) end) return {recolor = function() end, cleanup = function() conn:Disconnect() end} end STARTERS["Ice Aura"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local em = Instance.new("ParticleEmitter") em.Texture = SPARK em.LightEmission = 0.6 em.Rate = 30 em.Lifetime = NumberRange.new(1.2, 2) em.Speed = NumberRange.new(1, 3) em.Acceleration = Vector3.new(0, -1.5, 0) em.SpreadAngle = Vector2.new(180, 180) em.RotSpeed = NumberRange.new(-60, 60) em.Color = ColorSequence.new(Color3.fromRGB(170, 230, 255), Color3.fromRGB(255, 255, 255)) em.Size = NumberSequence.new({NSK(0, 0.35), NSK(1, 0.1)}) em.Transparency = NumberSequence.new({NSK(0, 0.1), NSK(1, 1)}) pcall(function() em.Shape = Enum.ParticleEmitterShape.Cylinder em.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume end) em.Parent = root local light = Instance.new("PointLight") light.Color = Color3.fromRGB(150, 220, 255) light.Range = 8 light.Brightness = 1.2 light.Parent = root return {cleanup = function() em:Destroy(); light:Destroy() end} end STARTERS["Cosmic Aura"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local stars = Instance.new("ParticleEmitter") stars.Texture = SPARK stars.LightEmission = 1 stars.Rate = 35 stars.Lifetime = NumberRange.new(1.5, 2.5) stars.Speed = NumberRange.new(0.5, 2) stars.SpreadAngle = Vector2.new(180, 180) stars.RotSpeed = NumberRange.new(-120, 120) stars.Color = ColorSequence.new({CSK(0, Color3.fromRGB(150, 80, 255)), CSK(0.5, Color3.fromRGB(80, 140, 255)), CSK(1, Color3.fromRGB(255, 100, 200))}) stars.Size = NumberSequence.new({NSK(0, 0.5), NSK(0.5, 0.35), NSK(1, 0)}) stars.Transparency = NumberSequence.new({NSK(0, 0.1), NSK(1, 1)}) pcall(function() stars.Shape = Enum.ParticleEmitterShape.Cylinder stars.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume end) stars.Parent = root local glow = Instance.new("ParticleEmitter") glow.Texture = "rbxasset://textures/particles/smoke_main.dds" glow.LightEmission = 1 glow.Rate = 4 glow.Lifetime = NumberRange.new(2, 2.5) glow.Speed = NumberRange.new(0, 0.5) glow.Color = ColorSequence.new(Color3.fromRGB(140, 90, 255), Color3.fromRGB(255, 110, 210)) glow.Size = NumberSequence.new({NSK(0, 4), NSK(1, 6.5)}) glow.Transparency = NumberSequence.new({NSK(0, 0.85), NSK(1, 1)}) glow.Parent = root return {cleanup = function() stars:Destroy(); glow:Destroy() end} end local active = {} local function stopEffect(name) local a = active[name] if a then pcall(a.cleanup); active[name] = nil end end local function startEffect(name) stopEffect(name) local char = LPl.Character if not char or not STARTERS[name] then return end local ok, res = pcall(STARTERS[name], char) if ok and res then active[name] = res end end local function setEffect(name, on) state[name] = on == true if on then startEffect(name) else stopEffect(name) end save() end local function recolorAll() for _, a in pairs(active) do if a.recolor then pcall(a.recolor, effectColor) end end end local conns = {} conns[#conns + 1] = LPl.CharacterRemoving:Connect(function() for name in pairs(active) do stopEffect(name) end end) conns[#conns + 1] = LPl.CharacterAdded:Connect(function(char) pcall(function() char:WaitForChild("HumanoidRootPart", 8) end) task.wait(0.6) for _, name in ipairs(EFFECTS) do if state[name] then startEffect(name) end end end) mkSect(page, "Cosmetic Effects") local swatchBtns = {} local hexBox local function refreshColorUI() local cur = toHex(effectColor) for i, b in ipairs(swatchBtns) do b.Text = (toHex(SWATCHES[i]) == cur) and "✓" or "" end if hexBox then hexBox.Text = cur end end local function setColor(c) effectColor = c refreshColorUI() recolorAll() save() end do local row = mkRow(page, 66) local l = mkLabel(row, "Effect Color") l.Size = UDim2.new(0.7, 0, 0, 26) for i, c in ipairs(SWATCHES) do local b = Instance.new("TextButton", row) b.Size = UDim2.new(1 / 8, -6, 0, 26) b.Position = UDim2.new((i - 1) / 8, 3, 0, 32) b.BackgroundColor3 = c b.BorderSizePixel = 0 b.Text = "" b.TextColor3 = Color3.new(1, 1, 1) b.Font = Enum.Font.GothamBold b.TextSize = 14 b.AutoButtonColor = false b.ZIndex = 9 Instance.new("UICorner", b).CornerRadius = UDim.new(0, 7) b.MouseButton1Click:Connect(function() setColor(c) end) swatchBtns[i] = b end end do local row = mkRow(page, 38) mkLabel(row, "HEX / RGB") hexBox = Instance.new("TextBox", row) hexBox.Size = UDim2.new(0, 140, 0, 26) hexBox.Position = UDim2.new(1, -148, 0.5, -13) hexBox.BackgroundColor3 = Color3.fromRGB(9, 20, 13) hexBox.BackgroundTransparency = 0.1 hexBox.BorderSizePixel = 0 hexBox.Text = toHex(effectColor) hexBox.PlaceholderText = "#FF5FBE ou 255,95,190" hexBox.TextColor3 = Color3.new(1, 1, 1) hexBox.Font = Enum.Font.GothamBold hexBox.TextSize = 11 hexBox.ClearTextOnFocus = false hexBox.ZIndex = 9 Instance.new("UICorner", hexBox).CornerRadius = UDim.new(0, 8) hexBox.FocusLost:Connect(function() local c = parseColor(hexBox.Text) if c then setColor(c) else hexBox.Text = toHex(effectColor) end end) end refreshColorUI() local setters = {} for _, name in ipairs(EFFECTS) do local setV = mkToggle(page, name, function(on) setEffect(name, on) end) setters[name] = setV setV(state[name] == true) end task.spawn(function() local waited = 0 while not (LPl.Character and LPl.Character:FindFirstChild("HumanoidRootPart")) and waited < 15 do task.wait(0.5); waited = waited + 0.5 end task.wait(0.5) for _, name in ipairs(EFFECTS) do if state[name] then startEffect(name) end end end) _G.__MonsterCosmeticsReset = function() for _, name in ipairs(EFFECTS) do state[name] = false stopEffect(name) if setters[name] then setters[name](false) end end effectColor = SWATCHES[4] refreshColorUI() save() end _G.__MonsterCosmetics = {Destroy = function() for name in pairs(active) do stopEffect(name) end for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end pcall(function() fxFolder:Destroy() end) end} end) if not okFx then warn("[Cosmetics] " .. tostring(errFx)) end end local configPage = contentPages["Config"] mkSect(configPage, "Auto Steal") setInstaGrab = mkToggle(configPage, "Auto Steal", function(on) local ok, err = pcall(function() CONFIG.AUTO_STEAL_ENABLED = on == true if on then pcall(startAutoSteal) else stopAutoSteal() end updateProgressBarVisibility() end) if not ok then warn("[monster] auto steal: " .. tostring(err)) end end) do local row = mkRow(configPage, 38) mkLabel(row, "Steal Radius") radInput = mkBox(row, CONFIG.STEAL_RANGE, 60, 68, function(v) v = _clamp(_floor(v + 0.5), 5, 300) CONFIG.STEAL_RANGE = v Steal.StealRadius = v radInput.Text = tostring(v) pcall(saveAllSettings) end) end if setInstaGrab then setInstaGrab(CONFIG.AUTO_STEAL_ENABLED == true) end mkSect(configPage, "UI Settings") do local row = mkRow(configPage, 38) mkLabel(row, "UI Scale") uiScaleBox = mkBox(row, uiScaleValue, 50, 56, function(v) local n = _clamp(_floor(v+0.5), 50, 150) uiScaleValue = n if mainUIScale then mainUIScale.Scale = n/100 end end) end do local row = mkRow(contentPages["Config"], 38) mkLabel(row, "Size Botões") local function sizeBtn(text, xOff) local b = Instance.new("TextButton", row) b.Size = UDim2.new(