end end if _unsuppressBodyLock then _unsuppressBodyLock(true) end end _batV3Track = _batV3Track or { targetRoot = nil, lastPos = nil, vel = Vector3.zero, smoothVel = Vector3.zero, lastSwing = 0, stickyUntil = 0, } _batV3Distance = tonumber(_batV3Distance) or 10.5 local _V3_CFG = { FOLLOW = 58, ACTIVATE = 10.5, MIN_DIST = 0.55, PRED = 0.16, AHEAD = 0.75, VEL_SMOOTH = 0.32, MAX_HVEL = 90, SWING_CD = 0.09, STICKY = 0.55, GRAVITY = 196.2, } local function _v3tools(char) if not char then return nil end local names={"Bat","Slap","Iron Slap","Gold Slap","Diamond Slap","Emerald Slap","Ruby Slap","Dark Matter Slap","Flame Slap","Nuclear Slap","Galaxy Slap","Glitched Slap"} for _,n in ipairs(names) do local t=char:FindFirstChild(n) if t and t:IsA("Tool") then return t end end for _,ch in ipairs(char:GetChildren()) do if ch:IsA("Tool") then local ln=string.lower(ch.Name) if string.find(ln,"bat",1,true) or string.find(ln,"slap",1,true) then return ch end end end local bp=LP:FindFirstChildOfClass("Backpack") if not bp then return nil end for _,n in ipairs(names) do local t=bp:FindFirstChild(n) if t and t:IsA("Tool") then return t end end for _,ch in ipairs(bp:GetChildren()) do if ch:IsA("Tool") then local ln=string.lower(ch.Name) if string.find(ln,"bat",1,true) or string.find(ln,"slap",1,true) then return ch end end end return nil end local function _v3pick(root) local T=_batV3Track local now=tick() if T.targetRoot and T.targetRoot.Parent and now < T.stickyUntil then local hum=T.targetRoot.Parent:FindFirstChildOfClass("Humanoid") if hum and hum.Health>0 then return T.targetRoot end end local best,bestD=nil,math.huge for _,plr in ipairs(Players:GetPlayers()) do if plr~=LP and plr.Character then local tr=plr.Character:FindFirstChild("HumanoidRootPart") local hum=plr.Character:FindFirstChildOfClass("Humanoid") if tr and hum and hum.Health>0 then local d=(tr.Position-root.Position).Magnitude if d<bestD then bestD,best=d,tr end end end end if best then T.targetRoot=best T.stickyUntil