nitude > 0.01 then local yawErr = (math.deg(math.atan2(-flatTo.X, -flatTo.Z)) - root.Orientation.Y + 180) % 360 - 180 local pitchErr = (math.deg(math.atan2(toAim.Y, flatTo.Magnitude)) - root.Orientation.X + 180) % 360 - 180 local yawVel = math.clamp(math.rad(yawErr) * 285, -28, 28) local pitchVel = math.clamp(math.rad(pitchErr) * 285, -28, 28) local yaw = math.rad(root.Orientation.Y) local right = Vector3.new(math.cos(yaw), 0, -math.sin(yaw)) root.AssemblyAngularVelocity = Vector3.new(0, yawVel, 0) + right * pitchVel else root.AssemblyAngularVelocity = Vector3.zero end local speed = math.clamp(tonumber(BAT_AIMBOT_SPEED) or 62, 1, 500) if dist < 6 then speed = speed * CFG.CLOSE_SLOW elseif dist > CFG.ACTIVATE * 1.6 then speed = speed * CFG.FAR_BOOST end if dist > CFG.ACTIVATE * CFG.SNAP_MULT * 2 then local snap = Vector3.new(aim.X, math.abs(aim.Y - myPos.Y) > 3 and aim.Y or myPos.Y, aim.Z) pcall(function() root.AssemblyLinearVelocity = Vector3.zero root.CFrame = CFrame.lookAt(snap, snap + (flatTo.Magnitude > 0.05 and flatTo.Unit or root.CFrame.LookVector)) end) else local chase = aim + dir * CFG.BEHIND + Vector3.new(0, CFG.UP, 0) - myPos local flatChase = Vector3.new(chase.X, 0, chase.Z) local horiz = flatChase.Magnitude > CFG.MIN_DIST and flatChase.Unit * speed or Vector3.zero local vert = math.abs(chase.Y) > 0.1 and Vector3.new(0, math.sign(chase.Y) * 52, 0) or Vector3.new(0, -2, 0) local lv = ensureMover(root, speed) local alpha = 1 - math.exp(-safeDt * 26) lv.VectorVelocity = lv.VectorVelocity:Lerp(horiz + vert, alpha) if flatChase.Magnitude > 0.5 then pcall(function() hum:Move(flatChase.Unit, false) end) end end if sethiddenproperty then pcall(sethiddenproperty, root, "PhysicsRepRootPart", target) end if dist <= CFG.ACTIVATE then swing(char, hum) end end local function disable() if conn then conn:Disconnect(); conn = nil end on = false local char = LP.Character local root = char and char:FindFirstChild("HumanoidRootPart") local hum = char and char:FindFirstChild