ck("<I4I2I2I4I4I2I2", 16, 1, 1, SAMPLE_RATE, SAMPLE_RATE * 2, 2, 16) .. "data" .. string.pack("<I4", #data) return header .. data end local DEFS = { click = { file = "monster_ui_click_v2.wav", total = 0.12, vol = 0.18, fallback = "rbxasset://sounds/button.wav", notes = { {f0 = 200, f1 = 80, start = 0, dur = 0.05, vol = 0.55, decay = 60}, {f0 = 1100, f1 = 1700, start = 0, dur = 0.09, vol = 0.40, decay = 50}, }, }, on = { file = "monster_ui_on_v2.wav", total = 0.32, vol = 0.16, fallback = "rbxasset://sounds/switch.wav", notes = { {f0 = 880, f1 = 880, start = 0, dur = 0.14, vol = 0.40, decay = 18}, {f0 = 1320, f1 = 1320, start = 0.07, dur = 0.24, vol = 0.40, decay = 14}, }, }, off = { file = "monster_ui_off_v2.wav", total = 0.32, vol = 0.16, fallback = "rbxasset://sounds/switch.wav", notes = { {f0 = 1320, f1 = 1320, start = 0, dur = 0.14, vol = 0.40, decay = 18}, {f0 = 880, f1 = 880, start = 0.07, dur = 0.24, vol = 0.40, decay = 14}, }, }, } local canSynth = type(writefile) == "function" and type(isfile) == "function" and (type(getcustomasset) == "function" or type(getsynasset) == "function") local assets = {} local function getAsset(kind) if assets[kind] then return assets[kind] end local d = DEFS[kind] local id = d.fallback if canSynth then local ok, res = pcall(function() if not isfile(d.file) then writefile(d.file, synthWav(d.notes, d.total)) end return (getcustomasset or getsynasset)(d.file) end) if ok and res then id = res end end assets[kind] = id return id end task.spawn(function() for kind in pairs(DEFS) do pcall(getAsset, kind) end end) local pool = {} _G.__MonsterUISound = function(kind) if not uiSoundsEnabled then return end pcall(function() kind = DEFS[kind] and kind or "click" local snd = pool[kind] if not (snd and snd.Parent) then snd = Instance.new("Sound") snd.Name = "MonsterUISound_" .. kind snd.SoundId = getAsset(kind) snd.Volume = DEFS[kind].vol snd.RollOffMaxDistance = 0 snd.Parent = SS pool[kind] = snd end snd.PlaybackSpeed = 0.97 + math.random() 